          "pinyin": "Gǎnxiè dǒngshìzhǎng de kěndìng. Wǒ cǐ cì de qiúzhí yìxiàng shì yùnyíng zǒngjiān, xīwàng néng jièzhù zhè yí píngtái fùnéng qǐyè chūhǎi.",
