          "meaning": "Chúng tôi sẽ thiết lập cơ chế họp ban giao ban liên phòng ban hàng tuần, lấy việc hạ giá thành tăng hiệu quả từ cách tân công nghệ làm mục tiêu chung, tính toán hài hòa mối quan tâm của các bên."
