          "pinyin": "Qībǎi-èrshí měiyuán shènzhì wúfǎ fùgài jīngmì héjīn de cǎigòu chéngběn, yóuyú yuáncáiliào zhǎng jià, wǒmen de lìrùn kōngjiān yǐjīng jíqí wéibó.",
          "meaning": "720 USD thậm chí không thể bù đắp chi phí thu mua hợp kim chính xác, do nguyên vật liệu tăng giá, biên lợi nhuận của chúng tôi đã vô cùng mỏng."
