          "pinyin": "Jìrán guì fāng zhǎnxiàn le kuòdà cǎigòu guīmó de chéngyì, wǒmen yuànyì gè ràng yí bù, dānjià dìng wéi qībǎi-liùshí měiyuán, bìng àn jǐdù fǎnlì.",
          "meaning": "Một khi quý bên đã thể hiện thiện chí mở rộng quy mô mua sắm, chúng tôi sẵn lòng mỗi bên nhượng bộ một bước, chốt đơn giá là 760 USD và có hoàn chiết khấu theo quý."
