          "meaning": "Căn cứ theo điều khoản FOB hai bên đã thống nhất, chúng tôi chịu trách nhiệm vận chuyển hàng hóa tới cảng bốc hàng Thượng Hải và hoàn tất thủ tục thông quan xuất khẩu."
