          "meaning": "Rất tốt! Nếu đối phương vẫn từ chối thương lượng và khăng khăng đòi bồi thường, chúng ta sẽ căn cứ điều khoản giải quyết tranh chấp, đệ trình Trung tâm Trọng tài Quốc tế Singapore phán xử."
