      "usageNotes": "\"病句\" là thuật ngữ chỉ câu sai ngữ pháp trong bài thi tiếng Trung; \"搭配不当\" là lỗi kết hợp từ ngữ cọc cạch; \"成分残缺\" là câu thiếu chủ ngữ hoặc vị ngữ.",
      "dialogue": [
        {
          "speaker": "A",
          "hanzi": "在HSK 6级阅读第二部分中，病句辨析往往是考生失分的重灾区。",
          "pinyin": "Zài HSK liù jí yuèdú dì èr bùfen zhōng, bìngjù biànxī wǎngwǎng shì kǎoshēng shī fēn de zhòngzāiqū.",
          "meaning": "Trong phần đọc hiểu thứ hai của đề thi HSK 6, việc nhận diện và phân tích câu sai ngữ pháp thường là vùng trọng điểm mất điểm của thí sinh."
        },
        {
          "speaker": "B",
          "hanzi": "老师，我发现很多病句读起来似乎很顺口，但细究成分却总觉得哪里不对劲。",
          "pinyin": "Lǎoshī, wǒ fāxiàn hěn duō bìngjù dú qǐlái sìhū hěn shùnkǒu, dàn xìjiū chéngfèn què zǒng juéde nǎlǐ bú duìjìn.",
          "meaning": "Thưa thầy, em thấy nhiều câu bệnh đọc lên có vẻ rất thuận miệng, nhưng soi kỹ thành phần câu thì lại luôn thấy sai sai ở đâu đó."
        },
        {
          "speaker": "A",
          "hanzi": "这就是典型的“搭配不当”或“成分残缺”。比如“通过这次考察，使我学到了很多”，滥用介词导致主语残缺。",
          "pinyin": "Zhè jiù shì diǎnxíng de \"dāpèi bùdàng\" huò \"chéngfèn cánquē\". Bǐrú \"tōngguò zhè cì kǎochá, shǐ wǒ xué dào le hěn duō\", lànyòng jiècí dǎozhì zhǔyǔ cánquē.",
          "meaning": "Đó chính là lỗi điển hình \"kết hợp cọc cạch\" hoặc \"khuyết thiếu thành phần\". Ví dụ \"Qua đợt khảo sát này, khiến tôi học được rất nhiều\", lạm dụng giới từ dẫn tới thiếu chủ ngữ."
        },
        {
          "speaker": "B",
          "hanzi": "原来如此！去掉“使”或者去掉“通过”，句子的主干成分才能完整显现。",
          "pinyin": "Yuánlái rúcǐ! Qùdiào \"shǐ\" huòzhě qùdiào \"tōngguò\", jùzi de zhǔgàn chéngfèn cáinéng wánzhěng xiǎnxiàn.",
          "meaning": "Thì ra là thế! Bỏ chữ \"sử\" đi hoặc bỏ chữ \"thông qua\" đi, thì thành phần nòng cốt của câu mới hiển hiện hoàn chỉnh."
        },
        {
          "speaker": "A",
          "hanzi": "完全正确。只要理清主谓宾主干，再排查修饰语语序颠倒，攻克病句题便能得心应手。",
          "pinyin": "Wánquán zhèngquè. Zhǐyào lǐqīng zhǔ-wèi-bīn zhǔgàn, zài páichá xiūshìyǔ yǔxù diāndǎo, gōngkè bìngjù tí biàn néng déxīn-yìngshǒu.",
          "meaning": "Hoàn toàn chính xác. Chỉ cần làm rõ nòng cốt Chủ - Vị - Tân, sau đó rà soát trật tự từ tu sức bị đảo lộn, việc chinh phục câu hỏi câu bệnh sẽ vô cùng thuận tay thuần thục."
        }
      ],
      "audioText": "攻克HSK 6级病句辨析的核心技巧在于抓取主谓宾主干。排查成分残缺、搭配不当与语序颠倒，能够帮助学习者从根本上提升书面语表达的严密性。",
